{
  "a_sentences": [
    {
      "a_text": "L'allocation pour impotent de l'assurance-invalidité ouvre le droit à un assistenzbeitrag aux assurés majeurs vivant à domicile, selon l'art. 42quater al. 1 LAI.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Les directives administratives ne peuvent pas introduire des restrictions allant au-delà de la loi et de l'ordonnance sur un droit matériel.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Le recours à l'instrument standardisé FAKT2 pour évaluer le besoin d'aide correspond à la volonté du législateur.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Le Tribunal fédéral a toutefois jugé que FAKT2 n'est pas un instrument approprié pour déterminer l'ensemble du besoin d'aide dans le domaine de l'éducation et de la garde d'enfants.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "Le Tribunal fédéral a récemment confirmé que le besoin d'aide doit être déterminé à l'aide de l'instrument standardisé FAKT2.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Un assistenzbeitrag est accordé pour les prestations d'aide nécessaires à l'assuré, fournies régulièrement par une personne naturelle.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La recourante a suffisamment tenu compte des circonstances individuelles de l'intimé, notamment en procédant à une enquête à domicile et en appliquant les ajustements prévus par les directives.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral admet le recours de l'assureur, confirme la décision du 7 février 2025 et renvoie la cause à la juridiction cantonale pour nouvelle répartition des frais.",
      "b_propositions": ["P8"]
    }
  ]
}
